import * as React from "react";
import { useState, useEffect }from "react";
import TopNav from "../topNav/TopNav";
import "./TopNavigation.scss";
import Button from "../button/Button";
import IconButton from "../iconButton/IconButton";
import SearchBar from "../topNav/SearchBar";
import TopNavBlock from "../topNavBlock/TopNavBlock";
import { SvgMpaIcon,SvgMpaLogo } from "../../assets/icons";
import { MpaLogo } from "../logo/MpaLogo";

export interface NavMenuItem  {
  label: string;
  leadingIcon?: keyof typeof SvgMpaIcon | string;
  showDivider?: boolean;
  disabled?: boolean;
  subMenuItems?: NavMenuItem[]; 
};

export interface TopNavigationProps {

    /**
    * Unique identifier for the topnavigation
    */
    id: string;

    /** Array of navigation items */
    navItems: {
        label: string;
        header?: string;
        desc?: string;
        link?: string;
        menuItems: {
          label: string;
          leadingIcon?: keyof typeof SvgMpaIcon | string;          
          showDivider?: boolean;
          disabled?: boolean;
          subMenuItems?: NavMenuItem[];
        }[];
    }[];

    /** Logo icon name or path */
    logo? : keyof typeof SvgMpaLogo | string;


    // logo : JSX.Element,    
    /** Layout type */
    layout?: "menu-block" | "mega-menu" ;

    /** Toggle for showing the search bar */
    showSearch?: boolean;

    /** Toggle for showing login button */
    showLogin?: boolean;

    /** Optional colour theme for buttons/icons */
    colour: "primary" | "secondary" | "tertiary";


    /**
     * Optional click handler.
     * You can use it to trigger a modal, redirect, or any custom logic.
     */
    loginOnClick?: (event: React.MouseEvent<HTMLButtonElement>) => void; 
    
}


const TopNavigation: React.FC<TopNavigationProps> = ({ id, navItems, layout = "menu-block", showSearch = true , logo = "MpaWhiteLogo",  showLogin= true , colour = "primary", loginOnClick }) => {

    // const [openIndex, setOpenIndex] = React.useState<number | null>(null);
    const [isSearchVisible, setSearchVisible] = useState(false);

    const [windowWidth, setWindowWidth] = useState(window.innerWidth);

    const showSearchBar = () => {
        setSearchVisible(!isSearchVisible); 
  
        if (!isSearchVisible) {
        //   setOpenIndex(null); 
        }
    };

    const searchBoxClass = `${isSearchVisible ? 'show' : 'hide'}`;
    const isMobile = windowWidth < 768;

    useEffect(() => {
        const handleResize = () => {
            setWindowWidth(window.innerWidth);
        };
        // Add event listener for resizing
        window.addEventListener('resize', handleResize);

        // Cleanup the event listener when the component is unmounted
        return () => {
            window.removeEventListener('resize', handleResize);
        };
    }, []); 

    return (
        <>
          {/* Conditional rendering based on mobile width */}
          {isMobile  ? (
            <>
            <div className="top-nav-mobile">
                <div className="main-top-nav">
                    <div className="logo-container">
                        {<MpaLogo logoName={logo} width={60} height={60}/>}  
                    </div>
                    <div className="header-action">

                        {showLogin && (
                        <div className="auth-container">
                            <Button id={"buttonId"} leadingIcon={"Lock"} onClick={loginOnClick} label="Login"></Button>
                        </div>
                        )}
                        
                        <div className={`search-container`}>
                            {showSearch && (
                            <IconButton 
                                id={"iconButtonId"}
                                className={`icon-btn icon-btn-square icon-btn-${colour}`} 
                                icon={isSearchVisible ? 'X' : 'Menu2'}
                                btnType={"standard"}
                                onClick={showSearchBar}
                            >
                            </IconButton>
                            )}
                        </div>
                    </div>
                </div>   
                         
                
            </div>
            <SearchBar className={`search-box ${searchBoxClass}`} buttonClassName={`icon-btn icon-btn-square icon-btn-${colour}`}/>
            {isSearchVisible && (
                <TopNavBlock id="topNavBlockId" navItems={navItems} colour={colour} />
            )} 
            </>

          ) : (
            <div>            
              <TopNav id={id} navItems={navItems} layout={layout} showSearch={showSearch} showLogin={showLogin} colour={colour} logo={logo}/>
            </div>
          )}
        </>
      );

};

export default TopNavigation;
